/** A BN254 field element: a bigint, a safe-integer number, or a decimal / 0x-hex string. */
export type FieldLike = bigint | number | string;

/** Bytes: a `Uint8Array`, an array of byte values, or a `0x`-hex string. */
export type Bytes = Uint8Array | readonly number[] | string;

/** `ZKID` (a circuit input struct). */
export interface ZKID {
  id: FieldLike;
  dob: FieldLike;
  country: FieldLike;
  nonce: FieldLike;
}

/** Every input the prover supplies. */
export interface ZkKycInputs {
  user: ZKID;
  maxDob: FieldLike;
  commitment: FieldLike;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface ZkKycPublicInputs {
  maxDob: FieldLike;
  commitment: FieldLike;
}

/** The public inputs as decoded from a proof (each gadget type in its struct form). */
export interface ZkKycPublicValues {
  maxDob: FieldLike;
  commitment: FieldLike;
}

