// ---- runtime (schema-driven; identical in every generated client) ----

export type SchemaType =
  | "field"
  | { uint: number }
  | { array: { of: SchemaType; len: number } }
  | { tuple: SchemaType[] }
  | { ref: string };

/** A struct type's natural encoding: what may be passed in place of the struct. */
export interface Encoding {
  /** The encoded length in bytes (else the fields' lengths summed). */
  bytes?: number;
  /** A number whose little-endian `limbs`-bit limbs are the struct's leaves. */
  limbs?: number;
  /** Fields back to back: these byte lengths, or each field type's own. */
  concat?: number[] | "fields";
  /** Accept a leading SEC1 `0x04` tag. */
  sec1?: boolean;
  /** A compressed Ed25519 point, decompressed to its two coordinate fields. */
  ed25519?: boolean;
}

export interface Schema {
  version: number;
  circuit: string;
  inputs: { name: string; visibility: "public" | "private"; type: SchemaType }[];
  types: Record<string, { struct: { name: string; type: SchemaType }[]; encoding?: Encoding }>;
  public_inputs: string[];
}

/** The subset of the `xark-wasm` module these clients use (any build target). */
export interface XarkWasm {
  prove(
    circuitXbc: Uint8Array,
    provingKey: Uint8Array,
    inputs: Record<string, string>,
  ): { proof: Uint8Array; publicInputs: Uint8Array };
  verify(verifyingKey: Uint8Array, proof: Uint8Array, publicInputs: Uint8Array): boolean;
}

/** BN254 scalar field modulus. */
export const FIELD_MODULUS =
  21888242871839275222246405745257275088548364400416034343698204186575808495617n;

const camel = (s: string): string =>
  s.replace(/(?!^)_([a-z0-9])(?!$)/g, (_, c: string) => c.toUpperCase());

function fieldValue(v: unknown, at: string): bigint {
  let x: bigint;
  if (typeof v === "bigint") x = v;
  else if (typeof v === "number") {
    if (!Number.isSafeInteger(v)) throw new RangeError(`${at}: ${v} is not a safe integer; pass a bigint or string`);
    x = BigInt(v);
  } else if (typeof v === "string") {
    try {
      x = BigInt(v.trim());
    } catch {
      throw new TypeError(`${at}: ${JSON.stringify(v)} is not a decimal or 0x-hex number`);
    }
  } else throw new TypeError(`${at}: expected a number, bigint, or string`);
  // Not reduced: a value that wraps would prove a different number than the one given.
  if (x < 0n || x >= FIELD_MODULUS) throw new RangeError(`${at}: ${String(v)} is not a field element (0 <= x < p)`);
  return x;
}

/** `Bytes` (a `Uint8Array`, byte values, or `0x`-hex) as a `Uint8Array`. */
function bytesOf(v: unknown, at: string): Uint8Array {
  if (v instanceof Uint8Array) return v;
  if (Array.isArray(v)) return Uint8Array.from(v as number[]);
  if (typeof v === "string") {
    const h = v.trim().replace(/^0x/i, "");
    if (h.length % 2 !== 0 || !/^[0-9a-f]*$/i.test(h)) throw new TypeError(`${at}: ${JSON.stringify(v)} is not 0x-hex bytes`);
    return Uint8Array.from({ length: h.length / 2 }, (_, i) => parseInt(h.slice(2 * i, 2 * i + 2), 16));
  }
  throw new TypeError(`${at}: expected bytes (a Uint8Array or 0x-hex string)`);
}

const beToBig = (b: Uint8Array): bigint => b.reduce((acc, x) => (acc << 8n) | BigInt(x), 0n);
const bigToBe32 = (v: bigint): Uint8Array => Uint8Array.from({ length: 32 }, (_, i) => Number((v >> BigInt(8 * (31 - i))) & 0xffn));

/** The leaf names of a value of `ty` at `leaf`, in flatten order. */
function leafNames(schema: Schema, ty: SchemaType, leaf: string, out: string[]): void {
  if (ty === "field" || "uint" in ty) out.push(leaf);
  else if ("array" in ty) for (let i = 0; i < ty.array.len; i++) leafNames(schema, ty.array.of, `${leaf}[${i}]`, out);
  else if ("tuple" in ty) ty.tuple.forEach((t, i) => leafNames(schema, t, `${leaf}.${i}`, out));
  else for (const f of schema.types[ty.ref].struct) leafNames(schema, f.type, `${leaf}.${f.name}`, out);
}

/** The encoded length of struct type `name`, in bytes. */
function encodedLen(schema: Schema, name: string): number {
  const e = schema.types[name].encoding!;
  if (e.bytes !== undefined) return e.bytes;
  return concatSizes(schema, name).reduce((a, b) => a + b, 0);
}

function concatSizes(schema: Schema, name: string): number[] {
  const def = schema.types[name];
  const c = def.encoding!.concat;
  if (Array.isArray(c)) return c;
  return def.struct.map((f) => {
    if (typeof f.type !== "object" || !("ref" in f.type)) throw new TypeError(`${name}.${f.name} has no byte length`);
    return encodedLen(schema, f.type.ref);
  });
}

function modPow(b: bigint, e: bigint, m: bigint): bigint {
  let r = 1n;
  b %= m;
  for (; e > 0n; e >>= 1n, b = (b * b) % m) if (e & 1n) r = (r * b) % m;
  return r;
}

/** Decompress an Ed25519 point (`y` little-endian, `x`'s sign in the top bit). */
function ed25519Decompress(c: Uint8Array, at: string): [bigint, bigint] {
  const p = (1n << 255n) - 19n;
  const d = 37095705934669439343138083508754565189542113879843219016388785533085940283555n;
  const sqrtM1 = 19681161376707505956807079304988542015446066515923890162744021073123829784752n;
  const yb = Uint8Array.from(c).reverse();
  const sign = BigInt(yb[0] >> 7);
  yb[0] &= 0x7f;
  const y = beToBig(yb);
  if (y >= p) throw new RangeError(`${at}: not an Ed25519 point`);
  const y2 = (y * y) % p;
  const u = (y2 + p - 1n) % p;
  const v = (d * y2 + 1n) % p;
  let x = (((u * modPow(v, 3n, p)) % p) * modPow((u * modPow(v, 7n, p)) % p, (p - 5n) / 8n, p)) % p;
  if ((v * ((x * x) % p)) % p !== u) x = (x * sqrtM1) % p;
  if ((v * ((x * x) % p)) % p !== u) throw new RangeError(`${at}: not an Ed25519 point`);
  if ((x & 1n) !== sign) x = (p - x) % p;
  return [x, y];
}

/** A number into struct type `name`'s limb leaves. */
function encodeNumber(schema: Schema, name: string, n: bigint, leaf: string, at: string, out: Record<string, string>): void {
  const bits = BigInt(schema.types[name].encoding!.limbs!);
  const leaves: string[] = [];
  leafNames(schema, { ref: name }, leaf, leaves);
  if (n < 0n || n >> (bits * BigInt(leaves.length)) !== 0n) throw new RangeError(`${at}: ${n} doesn't fit a ${name}`);
  leaves.forEach((l, i) => (out[l] = ((n >> (bits * BigInt(i))) & ((1n << bits) - 1n)).toString()));
}

/** Bytes in struct type `name`'s natural encoding into its leaves. */
function encodeBytes(schema: Schema, name: string, b: Uint8Array, leaf: string, at: string, out: Record<string, string>): void {
  const def = schema.types[name];
  const e = def.encoding!;
  const len = encodedLen(schema, name);
  if (e.sec1 && b.length === len + 1 && b[0] === 4) b = b.subarray(1);
  if (b.length !== len) throw new RangeError(`${at}: a ${name} is ${len} bytes, got ${b.length}`);
  if (e.limbs !== undefined) return encodeNumber(schema, name, beToBig(b), leaf, at, out);
  let sizes: number[];
  if (e.ed25519) {
    const [x, y] = ed25519Decompress(b, at);
    b = Uint8Array.from([...bigToBe32(x), ...bigToBe32(y)]);
    sizes = [32, 32];
  } else sizes = concatSizes(schema, name);
  let off = 0;
  def.struct.forEach((f, i) => {
    const chunk = b.subarray(off, off + sizes[i]);
    off += sizes[i];
    const l = `${leaf}.${f.name}`;
    if (typeof f.type === "object" && "ref" in f.type) encodeBytes(schema, f.type.ref, chunk, l, `${at}.${camel(f.name)}`, out);
    else out[l] = fieldValue(beToBig(chunk), `${at}.${camel(f.name)}`).toString();
  });
}

/** Flatten `value` of type `ty` into `out` under the compiler's leaf names. */
function flatten(schema: Schema, ty: SchemaType, value: unknown, leaf: string, at: string, out: Record<string, string>): void {
  if (ty === "field") {
    out[leaf] = fieldValue(value, at).toString();
  } else if ("uint" in ty) {
    if (typeof value === "string" || typeof value === "object") throw new TypeError(`${at}: expected an integer`);
    const neg = typeof value === "bigint" ? value < 0n : (value as number) < 0;
    const x = neg ? -1n : fieldValue(value, at);
    if (x < 0n || x >= 1n << BigInt(ty.uint))
      throw new RangeError(`${at}: ${String(value)} is outside u${ty.uint}`);
    out[leaf] = x.toString();
  } else if ("array" in ty) {
    const u8 = typeof ty.array.of === "object" && "uint" in ty.array.of && ty.array.of.uint === 8;
    const xs = (u8 && typeof value === "string" ? bytesOf(value, at) : value) as ArrayLike<unknown>;
    if (xs == null || typeof xs.length !== "number") throw new TypeError(`${at}: expected an array`);
    if (xs.length !== ty.array.len) throw new RangeError(`${at}: expected ${ty.array.len} elements, got ${xs.length}`);
    for (let i = 0; i < xs.length; i++) flatten(schema, ty.array.of, xs[i], `${leaf}[${i}]`, `${at}[${i}]`, out);
  } else if ("tuple" in ty) {
    const xs = value as readonly unknown[];
    if (!Array.isArray(xs) || xs.length !== ty.tuple.length) throw new TypeError(`${at}: expected a ${ty.tuple.length}-tuple`);
    ty.tuple.forEach((t, i) => flatten(schema, t, xs[i], `${leaf}.${i}`, `${at}[${i}]`, out));
  } else {
    const def = schema.types[ty.ref];
    // A value in the type's natural encoding: bytes, or a number for limbs.
    if (def.encoding && !(typeof value === "object" && value !== null && !(value instanceof Uint8Array) && !Array.isArray(value))) {
      const numeric = typeof value === "bigint" || typeof value === "number" || (typeof value === "string" && !/^0x/i.test(value.trim()));
      if (def.encoding.limbs !== undefined && numeric) {
        const n = typeof value === "bigint" ? value : BigInt(typeof value === "number" ? value : (value as string).trim());
        return encodeNumber(schema, ty.ref, n, leaf, at, out);
      }
      return encodeBytes(schema, ty.ref, bytesOf(value, at), leaf, at, out);
    }
    if (typeof value !== "object" || value === null) throw new TypeError(`${at}: expected a ${ty.ref} object`);
    const obj = value as Record<string, unknown>;
    for (const f of def.struct) {
      const key = camel(f.name);
      if (!(key in obj)) throw new TypeError(`${at}: missing \`${key}\``);
      flatten(schema, f.type, obj[key], `${leaf}.${f.name}`, `${at}.${key}`, out);
    }
  }
}

/** Rebuild a value of type `ty` from leaf values in flatten order. */
function unflatten(schema: Schema, ty: SchemaType, xs: bigint[], pos: { i: number }): unknown {
  if (ty === "field") return xs[pos.i++];
  if ("uint" in ty) {
    const x = xs[pos.i++];
    return ty.uint <= 32 ? Number(x) : x;
  }
  if ("array" in ty) {
    const items = Array.from({ length: ty.array.len }, () => unflatten(schema, ty.array.of, xs, pos));
    const of = ty.array.of;
    return typeof of === "object" && "uint" in of && of.uint === 8 ? Uint8Array.from(items as number[]) : items;
  }
  if ("tuple" in ty) return ty.tuple.map((t) => unflatten(schema, t, xs, pos));
  const obj: Record<string, unknown> = {};
  for (const f of schema.types[ty.ref].struct) obj[camel(f.name)] = unflatten(schema, f.type, xs, pos);
  return obj;
}

/** The flat `leaf → value` witness map for the given inputs (all of them, or only public). */
export function flattenInputs(schema: Schema, inputs: object, publicOnly = false): Record<string, string> {
  const out: Record<string, string> = {};
  const obj = inputs as Record<string, unknown>;
  for (const input of schema.inputs) {
    if (publicOnly && input.visibility !== "public") continue;
    const key = camel(input.name);
    if (!(key in obj)) throw new TypeError(`missing input \`${key}\``);
    flatten(schema, input.type, obj[key], input.name, key, out);
  }
  return out;
}

/** Public inputs → canonical compressed bytes (`public_inputs.bin`): u64 LE count, then 32-byte LE scalars. */
export function encodePublicInputs(schema: Schema, publicInputs: object): Uint8Array {
  const flat = flattenInputs(schema, publicInputs, true);
  const values = schema.public_inputs.map((leaf) => BigInt(flat[leaf]));
  const out = new Uint8Array(8 + 32 * values.length);
  new DataView(out.buffer).setBigUint64(0, BigInt(values.length), true);
  values.forEach((v, i) => {
    for (let b = 0; b < 32; b++) out[8 + 32 * i + b] = Number((v >> BigInt(8 * b)) & 0xffn);
  });
  return out;
}

/** Canonical public-input bytes → typed public inputs. */
export function decodePublicInputs(schema: Schema, bytes: Uint8Array): Record<string, unknown> {
  const n = Number(new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getBigUint64(0, true));
  if (n !== schema.public_inputs.length || bytes.length !== 8 + 32 * n)
    throw new RangeError(`expected ${schema.public_inputs.length} public inputs, got ${n}`);
  const xs = Array.from({ length: n }, (_, i) => {
    let v = 0n;
    for (let b = 31; b >= 0; b--) v = (v << 8n) | BigInt(bytes[8 + 32 * i + b]);
    return v;
  });
  const pos = { i: 0 };
  const out: Record<string, unknown> = {};
  for (const input of schema.inputs)
    if (input.visibility === "public") out[camel(input.name)] = unflatten(schema, input.type, xs, pos);
  return out;
}

// ---- `zk_kyc` client ----

/** A proof with its public inputs, decoded and as the canonical bytes `verify` takes. */
export interface ZkKycProof {
  proof: Uint8Array;
  publicInputs: ZkKycPublicValues;
  publicInputBytes: Uint8Array;
}

/**
 * Typed prover/verifier for `zk_kyc`, over the `xark-wasm` module you pass in:
 *
 * ```ts
 * import * as wasm from "@blueshift-gg/xark-wasm"; // node, web (after `await init()`), or bundler build
 * const circuit = new ZkKyc(wasm, { circuit: xbc, provingKey: pk, verifyingKey: vk });
 * const { proof, publicInputs } = circuit.prove(inputs);
 * circuit.verify(proof, publicInputs); // true
 * ```
 */
export class ZkKyc {
  static readonly schema: Schema = ZK_KYC_SCHEMA;

  constructor(
    private readonly wasm: XarkWasm,
    private readonly keys: { circuit?: Uint8Array; provingKey?: Uint8Array; verifyingKey?: Uint8Array },
  ) {}

  /** The flat witness map (`leaf → decimal`) for `xark prove --inputs` or the wasm prover. */
  static witness(inputs: ZkKycInputs): Record<string, string> {
    return flattenInputs(ZK_KYC_SCHEMA, inputs);
  }

  static encodePublicInputs(publicInputs: ZkKycPublicInputs): Uint8Array {
    return encodePublicInputs(ZK_KYC_SCHEMA, publicInputs);
  }

  static decodePublicInputs(bytes: Uint8Array): ZkKycPublicValues {
    return decodePublicInputs(ZK_KYC_SCHEMA, bytes) as unknown as ZkKycPublicValues;
  }

  prove(inputs: ZkKycInputs): ZkKycProof {
    const { circuit, provingKey } = this.keys;
    if (!circuit || !provingKey) throw new Error("proving needs `circuit` (circuit.xbc) and `provingKey` (pk.bin)");
    const bundle = this.wasm.prove(circuit, provingKey, ZkKyc.witness(inputs));
    const publicInputBytes = bundle.publicInputs.slice();
    return {
      proof: bundle.proof.slice(),
      publicInputs: ZkKyc.decodePublicInputs(publicInputBytes),
      publicInputBytes,
    };
  }

  verify(proof: Uint8Array, publicInputs: ZkKycPublicInputs | ZkKycPublicValues | Uint8Array): boolean {
    const { verifyingKey } = this.keys;
    if (!verifyingKey) throw new Error("verifying needs `verifyingKey` (vk.bin)");
    const bytes = publicInputs instanceof Uint8Array ? publicInputs : ZkKyc.encodePublicInputs(publicInputs);
    try {
      return this.wasm.verify(verifyingKey, proof, bytes);
    } catch {
      return false; // malformed proof bytes
    }
  }
}
